<section class="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-5"><?php foreach ([['Registros', (int) ($stats['total'] ?? 0)], ['Por gestionar', (int) ($stats['por_gestionar'] ?? 0)], ['Vigentes', (int) ($stats['vigentes'] ?? 0)], ['Vencidos sin cerrar', (int) ($stats['vencidos'] ?? 0)], ['Cerrados', (int) ($stats['cerrados'] ?? 0)]] as $metric): ?><div class="ios-card p-4"><p class="text-[11px] text-slate-400"><?= e($metric[0]) ?></p><p class="mt-2 text-2xl font-semibold"><?= $metric[1] ?></p></div><?php endforeach; ?></section>
