<?php if ($permits === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('clipboard', 'h-7 w-7') ?></span><h3>No hay permisos en esta vista</h3><p>Genera un permiso o cambia los filtros aplicados.</p></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Permiso y tarea</th><th>Tipo</th><th>Ubicación</th><th>Vigencia</th><th>Responsable</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($permits as $permit): ?><?php $expired = in_array($permit['estado'], ['Aprobado','Activo'], true) && strtotime($permit['fecha_fin']) < time(); ?><tr><td><p class="font-mono text-[10px] font-semibold text-blue-600"><?= e($permit['codigo']) ?> · v<?= (int) $permit['version'] ?></p><p class="mt-1 max-w-[280px] text-xs font-semibold leading-5 text-slate-700"><?= e($permit['tarea']) ?></p></td><td><span class="badge badge-gray"><?= e($typeLabels[$permit['tipo']] ?? $permit['tipo']) ?></span></td><td class="max-w-[180px] text-xs text-slate-500"><?= e($permit['ubicacion']) ?></td><td class="whitespace-nowrap text-[11px] text-slate-500"><?= format_date($permit['fecha_inicio']) ?><br><?= e(date('H:i', strtotime($permit['fecha_inicio']))) ?> — <?= e(date('H:i', strtotime($permit['fecha_fin']))) ?></td><td class="text-xs text-slate-600"><?= e($permit['responsable_trabajo']) ?></td><td><span class="badge <?= $expired ? 'badge-red' : status_class($permit['estado']) ?>"><?= $expired ? 'Vencido' : e($permit['estado']) ?></span></td><td><a href="<?= e(url('/permisos-trabajo/' . $permit['id'])) ?>" class="text-link whitespace-nowrap">Gestionar <?= icon('arrow-right', 'h-3.5 w-3.5') ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
